const DB_NAME="my-state-local", DB_VERSION=4;
const STORES=["meds","mood","sleep","diary","traits","medLogs","traitHistory","criticality","goals"];
const PHASES=["depression","mixed","remission","hypomania","mania"];
const PHASE_LABELS={depression:"Депрессивная",mixed:"Смешанная",remission:"Ремиссия",hypomania:"Гипоманиакальная",mania:"Маниакальная"};
const MOOD_LABELS=["пропасть","очень тяжело","тяжело","нормально","хорошо","слишком хорошо"];
let db,diaryRange=null;
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result;for(const s of STORES)if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:"id",autoIncrement:true});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function all(store){return new Promise((resolve,reject)=>{const r=db.transaction(store,"readonly").objectStore(store).getAll();r.onsuccess=()=>resolve(r.result.sort((a,b)=>(b.created||"").localeCompare(a.created||"")));r.onerror=()=>reject(r.error);});}
function add(store,v){return new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite"),r=tx.objectStore(store).add({...v,created:new Date().toISOString()});let id;r.onsuccess=()=>{id=r.result;};tx.oncomplete=()=>resolve(id);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Transaction aborted"));});}
function put(store,v){return new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite");tx.objectStore(store).put(v);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
function remove(store,id){return new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite");tx.objectStore(store).delete(Number(id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
function esc(v=""){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function fmt(v){const lang=localStorage.getItem("my-state-language")||"ru";const locale=lang==="pl"?"pl-PL":lang==="en"?"en-GB":"ru-RU";return v?new Date(v).toLocaleString(locale):"";}
function localDateTime(){const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16);}
function localDate(){return localDateTime().slice(0,10);}
function formObject(f){return Object.fromEntries(new FormData(f).entries());}
function show(view){document.querySelectorAll(".view").forEach(x=>x.classList.toggle("active",x.id===`view-${view}`));document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x.dataset.view===view));({home:renderHomeMeds,meds:renderMeds,mood:renderMood,sleep:renderSleep,diary:renderDiary,personality:renderTraits,criticality:renderIdeas,goals:renderGoals})[view]?.();}
document.querySelectorAll("[data-view]").forEach(b=>b.addEventListener("click",()=>show(b.dataset.view)));
document.querySelectorAll("[data-go]").forEach(b=>b.addEventListener("click",()=>show(b.dataset.go)));
function card(title,sub,body,store,id){return `<article class="entry"><div class="entry-title">${esc(title)}</div><small>${esc(sub||"")}</small>${body||""}<div class="entry-actions"><button class="delete" data-delete="${store}:${id}">Удалить</button></div></article>`;}
document.addEventListener("click",async e=>{
 const del=e.target.closest("[data-delete]");if(del){const [st,id]=del.dataset.delete.split(":");if(confirm(trUI("Удалить эту запись?"))){await remove(st,id);refreshAll();}return;}
 const take=e.target.closest("[data-take]");if(take){const [medId,period]=take.dataset.take.split("|");await add("medLogs",{medId:Number(medId),period,date:localDate(),takenAt:new Date().toISOString()});renderMeds();renderHomeMeds();return;}
 const toggle=e.target.closest("[data-collapse]");if(toggle){const el=document.getElementById(toggle.dataset.collapse);if(el){el.hidden=!el.hidden;toggle.textContent=el.hidden?"Показать дни":"Свернуть дни";}return;}
 const assess=e.target.closest("[data-assess]");if(assess){const id=Number(assess.dataset.assess),wrap=document.querySelector(`#assessment-${id}`);if(wrap)wrap.hidden=!wrap.hidden;return;}
 const saveAssess=e.target.closest("[data-save-assess]");if(saveAssess){const id=Number(saveAssess.dataset.saveAssess),item=(await all("criticality")).find(x=>x.id===id),wrap=document.querySelector(`#assessment-${id}`);if(!item||!wrap)return;const value=wrap.querySelector("select").value;if(!value)return;const now=new Date(),day=localDate(),moods=await all("mood"),same=moods.filter(m=>(m.date||"").slice(0,10)===day&&m.phase).sort((a,b)=>(b.date||"").localeCompare(a.date||""));const history=[...(item.assessmentHistory||[]),{assessment:assessmentLabel(value),assessmentCode:value,date:now.toISOString(),phase:same[0]?.phase||"Фаза не указана"}];await put("criticality",{...item,assessment:value,assessedAt:now.toISOString(),assessmentPhase:same[0]?.phase||"",assessmentHistory:history});renderIdeas();await syncGoals();renderGoals();return;}
});
async function renderMeds(){const [items,logs]=await Promise.all([all("meds"),all("medLogs")]);document.querySelector("#med-list").innerHTML=items.map(m=>{const ml=logs.filter(l=>l.medId===m.id),dates=[...new Set([...ml.map(l=>l.date),localDate()])].sort().reverse(),active=(m.doses||[]).map(d=>d.period),bodyId=`med-days-${m.id}`;const rows=dates.map(date=>{const cells=["Утро","Обед","Вечер"].map(period=>{const n=ml.filter(l=>l.date===date&&l.period===period).length;const action=active.includes(period)&&date===localDate()?`<button class="secondary" data-take="${m.id}|${period}">Отметить</button>`:"·";return `<td>${n?`✓${n>1?` × ${n}`:""}<br>`:""}${action}</td>`}).join("");return `<tr><td>${esc(date)}</td>${cells}</tr>`}).join("");return `<article class="entry"><div class="entry-title">${esc(m.name)} · ${esc(m.doseMg??"—")} мг</div><small>${(m.doses||[]).map(d=>esc(d.period)).join(", ")} · ${(m.doses||[]).length} приём(а) в день</small><p><button class="text-button" data-collapse="${bodyId}">Показать дни</button></p><div id="${bodyId}" class="table-wrap" hidden><table><thead><tr><th>Дата</th><th>Утро</th><th>Обед</th><th>Вечер</th></tr></thead><tbody>${rows||`<tr><td colspan="4">Отметок пока нет</td></tr>`}</tbody></table></div><div class="entry-actions"><button class="delete" data-delete="meds:${m.id}">Удалить препарат</button></div></article>`}).join("")||"<p class='muted'>Препаратов пока нет.</p>";}
async function renderHomeMeds(){const [items,logs]=await Promise.all([all("meds"),all("medLogs")]);document.querySelector("#home-med-checks").innerHTML=items.map(m=>{const periods=(m.doses||[]).map(d=>d.period);return `<article class="entry"><b>${esc(m.name)} · ${esc(m.doseMg)} мг</b><div class="dose-grid">${periods.map(period=>{const n=logs.filter(l=>l.medId===m.id&&l.date===localDate()&&l.period===period).length;return `<div class="dose-status"><span>${period}</span><b>${n?`Отмечено: ${n}`:"Не отмечено"}</b><button class="secondary" data-take="${m.id}|${period}">${n?"Ещё раз":"Отметить"}</button></div>`}).join("")}</div></article>`}).join("")||"Препаратов пока нет.";}
async function renderMood(){const a=await all("mood");document.querySelector("#mood-list").innerHTML=a.map(x=>card(`${x.score}/5 · ${MOOD_LABELS[x.score]||""}`,`${fmt(x.date)}${x.phase?" · Фаза: "+x.phase:" · Фаза не указана"}`,`<p>Гипервоодушевление: ${x.enthusiasm??0}/100${x.enthusiasmNote?" · "+esc(x.enthusiasmNote):""}</p><p>Раздражительность: ${x.irritability??0}/100${x.irritabilityNote?" · "+esc(x.irritabilityNote):""}</p><p>Пустота: ${x.emptiness??0}${x.emptinessNote?" · "+esc(x.emptinessNote):""}</p>${x.note?`<p>${esc(x.note)}</p>`:""}`,"mood",x.id)).join("")||"<p class='muted'>Оценок пока нет.</p>";}
async function renderSleep(){const a=await all("sleep");document.querySelector("#sleep-list").innerHTML=a.map(x=>card("Сон",`${x.date} · ${x.bed}–${x.wake}`,`<p>${x.woke==="yes"?"Ночные пробуждения: "+(x.wakeIntervals||[]).map(t=>esc(t.from)+"–"+esc(t.to)).join(", "):"Ночных пробуждений не было"}</p>${x.dream?`<p><b>Описание сна:</b> ${esc(x.dream)}</p>`:""}${x.note?`<p>${esc(x.note)}</p>`:""}`,"sleep",x.id)).join("")||"<p class='muted'>Записей о сне пока нет.</p>";}
async function renderDiary(){let a=await all("diary");if(diaryRange)a=a.filter(x=>x.date.slice(0,10)>=diaryRange.from&&x.date.slice(0,10)<=diaryRange.to);document.querySelector("#diary-list").innerHTML=a.map(x=>card("Запись",fmt(x.date),`${x.body?`<p>${esc(x.body)}</p>`:""}`,"diary",x.id)).join("")||"<p class='muted'>Записей за этот период нет.</p>";}
async function renderTraits(){const a=await all("traits"),hist=await all("traitHistory");let html=a.length?`<div class="table-wrap"><table class="traits-table"><thead><tr><th>Сфера</th>${PHASES.map(k=>`<th>${PHASE_LABELS[k]}</th>`).join("")}<th>Действия</th></tr></thead><tbody>${a.map(x=>`<tr><th>${esc(x.topic)}</th>${PHASES.map(k=>`<td>${esc(x[k]||"")}</td>`).join("")}<td><button class="secondary" data-edit-trait="${x.id}">Изменить</button></td></tr>`).join("")}</tbody></table></div>`:"<p class='muted'>Добавь первую сферу наблюдения.</p>";document.querySelector("#trait-list").innerHTML=html;document.querySelector("#trait-history").innerHTML=hist.map(h=>`<article class="entry"><b>${esc(h.topic)}</b><small>${fmt(h.changedAt)}</small><p>${esc(h.details)}</p></article>`).join("")||"Изменений пока нет.";}
document.querySelector("#trait-list").addEventListener("click",async e=>{const b=e.target.closest("[data-edit-trait]");if(!b)return;const item=(await all("traits")).find(x=>x.id===Number(b.dataset.editTrait));if(!item)return;const f=document.createElement("form");f.className="panel";f.innerHTML=`<h3>Редактировать: ${esc(item.topic)}</h3><label>Сфера<input name="topic" required value="${esc(item.topic)}"></label>${PHASES.map(k=>`<label>${PHASE_LABELS[k]}<textarea name="${k}" rows="2">${esc(item[k]||"")}</textarea></label>`).join("")}<button class="primary">Сохранить изменения</button><button type="button" class="text-button" id="cancel-edit">Отмена</button>`;document.querySelector("#trait-list").prepend(f);f.querySelector("#cancel-edit").onclick=()=>f.remove();f.onsubmit=async ev=>{ev.preventDefault();const v=formObject(f),changed=[];for(const k of ["topic",...PHASES])if((item[k]||"")!==(v[k]||""))changed.push(`${k==="topic"?"Сфера":PHASE_LABELS[k]}: «${item[k]||""}» → «${v[k]||""}»`);if(changed.length){await add("traitHistory",{traitId:item.id,topic:item.topic,changedAt:new Date().toISOString(),details:changed.join("; ")});await put("traits",{...item,...v,updated:new Date().toISOString()});}f.remove();renderTraits();};});
async function renderRecent(){const [m,d,s]=await Promise.all([all("mood"),all("diary"),all("sleep")]);const rows=[...m.slice(0,2).map(x=>`Настроение ${x.score}/5 · ${MOOD_LABELS[x.score]} · ${fmt(x.date)}`),...s.slice(0,2).map(x=>`Сон · ${x.date}`),...d.slice(0,2).map(x=>`Дневник · ${fmt(x.date)}`)].slice(0,5);document.querySelector("#recent").innerHTML=rows.length?rows.map(x=>`<p>${esc(x)}</p>`).join(""):"Пока записей нет.";}
// Medication schedule editor
const periodNames=["Утро","Обед","Вечер"];
function renderDoseTimes(){const selected=[...document.querySelectorAll('input[name="period"]:checked')];document.querySelector("#times-per-day").value=String(selected.length||1);}
document.querySelectorAll('input[name="period"]').forEach(x=>x.addEventListener("change",()=>{const checked=[...document.querySelectorAll('input[name="period"]:checked')];if(checked.length>3){x.checked=false;return;}renderDoseTimes();}));
document.querySelector("#times-per-day").addEventListener("change",e=>{const n=Number(e.target.value);document.querySelectorAll('input[name="period"]').forEach((x,i)=>x.checked=i<n);renderDoseTimes();});renderDoseTimes();
document.querySelector("#med-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,v=formObject(f),periods=[...f.querySelectorAll('input[name="period"]:checked')];if(!periods.length){alert(trUI("Выбери хотя бы один период приёма."));return;}if(periods.length!==Number(v.timesPerDay)){alert(trUI("Количество периодов должно совпадать с числом приёмов."));return;}v.doses=periods.map(x=>({period:x.value}));delete v.timesPerDay;await add("meds",v);f.reset();f.querySelector('input[name="period"][value="Утро"]').checked=true;renderDoseTimes();renderMeds();});
const moodRange=document.querySelector("#mood-range"),moodValue=document.querySelector("#mood-value");function updateMood(){moodValue.textContent=`${moodRange.value} · ${MOOD_LABELS[Number(moodRange.value)]}`;}moodRange.addEventListener("input",updateMood);
function bindScale(id,label,zero,full){const r=document.querySelector(id),out=document.querySelector(label);const upd=()=>{const n=Number(r.value);out.textContent=`${n} · ${n===0?zero:full}`;};r.addEventListener("input",upd);upd();}function bindThree(id,label,labels){const r=document.querySelector(id),out=document.querySelector(label);const upd=()=>out.textContent=`${r.value} · ${labels[Number(r.value)]}`;r.addEventListener("input",upd);upd();}bindThree("#enth-range","#enth-value",["нет","есть","полёт в космос"]);bindThree("#irrit-range","#irrit-value",["нет","есть","всё бесит"]);bindThree("#empty-range","#empty-value",["нет","болит в груди","невыносимая пустота в груди"]);
document.querySelector("#mood-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,v=formObject(f);v.score=Number(v.score);await add("mood",v);f.reset();f.elements.date.value=localDateTime();updateMood();document.querySelectorAll("#enth-range,#irrit-range,#empty-range").forEach(x=>x.dispatchEvent(new Event("input")));renderMood();});
function addWakeRow(from="",to=""){const row=document.createElement("div");row.className="wake-row";row.innerHTML=`<label>Проснулась<input type="time" class="wake-from" value="${esc(from)}"></label><label>Заснула снова<input type="time" class="wake-to" value="${esc(to)}"></label><button type="button" aria-label="Удалить интервал">×</button>`;row.querySelector("button").onclick=()=>row.remove();document.querySelector("#wake-times").append(row);}
document.querySelectorAll('input[name="woke"]').forEach(x=>x.addEventListener("change",()=>document.querySelector("#wake-times-wrap").hidden=document.querySelector('input[name="woke"]:checked').value!=="yes"));
document.querySelector("#add-wake").onclick=()=>addWakeRow();
document.querySelector("#sleep-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,v=formObject(f);v.wakeIntervals=[...document.querySelectorAll(".wake-row")].map(r=>({from:r.querySelector(".wake-from").value,to:r.querySelector(".wake-to").value})).filter(x=>x.from||x.to);if(v.woke==="yes"&&(!v.wakeIntervals.length||v.wakeIntervals.some(x=>!x.from||!x.to))){alert(trUI("Для каждого пробуждения укажи оба времени: когда проснулась и когда снова заснула."));return;}await add("sleep",v);f.reset();f.elements.date.value=localDate();f.elements.bed.value="23:00";f.elements.wake.value="07:00";document.querySelector("#wake-times").innerHTML="";document.querySelector("#wake-times-wrap").hidden=true;addWakeRow();renderSleep();});
document.querySelector("#diary-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,v=formObject(f);if(!v.body.trim()){alert(trUI("Добавь текст записи."));return;}await add("diary",v);f.reset();f.elements.date.value=localDateTime();diaryRange=null;renderDiary();});
document.querySelector("#diary-filter").onclick=async()=>{const from=document.querySelector("#diary-from").value,to=document.querySelector("#diary-to").value;if(!from||!to||from>to){alert(trUI("Укажи корректный диапазон дат."));return;}diaryRange={from,to};renderDiary();};
document.querySelector("#diary-clear").onclick=()=>{diaryRange=null;document.querySelector("#diary-from").value="";document.querySelector("#diary-to").value="";renderDiary();};
document.querySelector("#trait-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget;await add("traits",formObject(f));f.reset();renderTraits();});
function csvCell(v){return `"${String(v??"").replace(/"/g,'""')}"`;}
function download(name,content,type="text/csv;charset=utf-8"){
 const blob=new Blob(["\uFEFF",content],{type}),url=URL.createObjectURL(blob);
 const status=document.querySelector("#export-status");
 const a=document.createElement("a");a.href=url;a.download=name;a.textContent=`Скачать файл: ${name}`;a.className="download-link";
 status.replaceChildren(document.createTextNode("Файл подготовлен. Если загрузка не началась автоматически, нажмите ссылку: "),a);
 a.click();
 // Keep the object URL alive for Safari/iOS; revoke only when the page is closed.
 window.addEventListener("pagehide",()=>URL.revokeObjectURL(url),{once:true});
}
const exports={meds:{headers:["Название","Дозировка одного приёма, мг","Периодичность","Дни","Периоды приёма"],map:x=>[x.name,x.doseMg,x.frequency,x.days,(x.doses||[]).map(d=>d.period).join("; ")]},mood:{headers:["Дата и время","Оценка","Описание","Гипервоодушевление","Комментарий к гипервоодушевлению","Раздражительность","Комментарий к раздражительности","Пустота","Комментарий к пустоте","Предполагаемая фаза","Комментарий"],map:x=>[x.date,x.score,MOOD_LABELS[x.score],x.enthusiasm,x.enthusiasmNote,x.irritability,x.irritabilityNote,x.emptiness,x.emptinessNote,x.phase,x.note]},sleep:{headers:["Дата","Время отхода ко сну","Время пробуждения","Ночные интервалы","Описание сна","Комментарий"],map:x=>[x.date,x.bed||"23:00",x.wake||"07:00",(x.wakeIntervals||[]).map(t=>`${t.from}–${t.to}`).join("; "),x.dream,x.note]},diary:{headers:["Дата и время","Основная запись"],map:x=>[x.date,x.body]},traits:{headers:["Сфера",...PHASES.map(k=>PHASE_LABELS[k])],map:x=>[x.topic,...PHASES.map(k=>x[k]||"")]},medLogs:{headers:["Дата","Лекарство","Период","Количество отметок","Суммарная дозировка, мг"],map:x=>{const med=window.__medExportCache?.find(m=>m.id===x.medId);return [x.date,med?.name||x.medId,x.period,x.count||1,(Number(med?.doseMg)||0)*(x.count||1)]}},traitHistory:{headers:["Сфера","Дата изменения","Изменения"],map:x=>[x.topic,x.changedAt,x.details]},criticality:{headers:["Идея","Дата создания","Фаза на дату создания","Оценка адекватности","История оценок","Комментарий"],map:x=>[x.idea,x.date,x.phase||"Фаза не указана",x.assessment,(x.assessmentHistory||[]).map(h=>`${h.date}: ${h.assessment}; фаза: ${h.phase}`).join(" | "),x.note]},goals:{headers:["Цель","Подцель","Срок, дни","Плановая дата","Дата исполнения","Стоимость","Валюта"],map:x=>[x.title,x.subgoal||"",x.days||0,x.due||"",x.doneDate||"",x.cost||0,x.currency||"EUR"]}};
for(const b of document.querySelectorAll("[data-export]"))b.addEventListener("click",async()=>{const key=b.dataset.export;let a=await all(key);if(key==="sleep")a=sleepExportRows(a);if(key==="goals"){a=a.flatMap(x=>x.subgoals?.length?x.subgoals.map(s=>({...x,...s})): [{...x,title:x.title,subgoal:""}]);}if(key==="medLogs"){const meds=await all("meds");window.__medExportCache=meds;const g={};for(const l of a){const k=[l.medId,l.date,l.period].join("|");if(!g[k])g[k]={...l,count:0};g[k].count++;}a=Object.values(g);}const sp=exports[key],dict=LANG[localStorage.getItem("my-state-language")||"ru"]||{},csv=[sp.headers.map(x=>translateString(x,dict)),...a.map(sp.map)].map(r=>r.map(csvCell).join(";")).join("\r\n");download(`${key}.csv`,csv);});
function sleepExportRows(records){if(!records.length)return [];const byDate=new Map(records.map(x=>[x.date,x]));const dates=records.map(x=>x.date).filter(Boolean).sort();const start=new Date(dates[0]+"T12:00:00"),end=new Date(localDate()+"T12:00:00"),out=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){const key=d.toISOString().slice(0,10),item=byDate.get(key);out.push(item||{date:key,bed:"23:00",wake:"07:00",wakeIntervals:[],dream:"",note:""});}return out;}
// Criticality: bind the idea to the last phase assessment saved on its creation date.
async function renderIdeas(){const a=await all("criticality");document.querySelector("#idea-list").innerHTML=a.map(x=>`<article class="entry"><div class="entry-title">${esc(x.idea)}</div><small>${esc(x.date)} · Фаза создания: ${esc(x.phase||"Фаза не указана")}</small><p>Последняя оценка: ${esc(assessmentLabel(x.assessment))}</p>${(x.assessmentHistory||[]).map(h=>`<p class="small">${fmt(h.date)} · ${esc(h.assessment)} · Фаза: ${esc(h.phase||"Фаза не указана")}</p>`).join("")}${x.note?`<p>${esc(x.note)}</p>`:""}<button class="secondary" data-assess="${x.id}">Изменить оценку</button><button type="button" class="delete" data-delete-idea="${x.id}">Удалить идею</button><div class="assessment-editor" id="assessment-${x.id}" hidden><label>Новая оценка<select><option value="">Выбрать оценку</option><option value="reasonable">Адекватная</option><option value="questionable">Сомнительная</option><option value="unreasonable">Неадекватная</option><option value="defer">Отложить до повторной оценки</option></select></label><button class="primary" data-save-assess="${x.id}">Сохранить оценку</button></div></article>`).join("")||"<p class='muted'>Идей пока нет.</p>";}
function isReasonableAssessment(value){return ["reasonable","Адекватная","Zasadna","Reasonable"].includes(String(value||"").trim());}
function assessmentLabel(value){return ({reasonable:"Адекватная",questionable:"Сомнительная",unreasonable:"Неадекватная",defer:"Отложить до повторной оценки"})[value]||value||"Пока не оценивалась";}
async function syncGoals(){const ideas=await all("criticality"),goals=await all("goals");for(const idea of ideas){if(isReasonableAssessment(idea.assessment)&&!idea.goalDeleted&&!goals.some(g=>g.ideaId===idea.id)){await add("goals",{ideaId:idea.id,title:idea.idea,createdAt:idea.date||new Date().toISOString(),subgoals:[]});}}for(const goal of goals){const idea=ideas.find(i=>i.id===goal.ideaId);if(idea&&!isReasonableAssessment(idea.assessment))await remove("goals",goal.id);} }
async function renderGoals(){
 await syncGoals();const goals=await all("goals");
 const legacyCurrency=localStorage.getItem("my-state-currency")||"EUR";for(const g of goals){if(!g.currency){g.currency=legacyCurrency;await put("goals",g);}}
 document.querySelector("#goals-list").innerHTML=goals.map(g=>{
  const subs=g.subgoals||[],cur=g.currency||"EUR",days=g.daysOverride??subs.reduce((n,s)=>n+(Number(s.days)||0),0),cost=g.costOverride??subs.reduce((n,s)=>n+(Number(s.cost)||0),0),created=(g.created||g.createdAt||"").slice(0,10)||"Дата не указана",achieved=subs.length>0&&subs.every(s=>s.completed===true||!!s.doneDate);
  return `<article class="entry goal-entry"><details class="goal-details"><summary><span class="goal-title">${esc(g.title)}</span>${achieved?`<span class="goal-achieved">Достигнута</span>`:""}<small> · ${esc(created)}</small><button type="button" class="secondary goal-edit-icon" data-edit-goal="${g.id}" aria-label="Изменить цель" title="Изменить цель">✎</button><span class="goal-totals">Суммарный срок: ${days} дней<br>Суммарная стоимость: ${money(cost,cur)}</span></summary>
  <label class="goal-currency">Валюта цели<select data-goal-currency="${g.id}"><option value="EUR" ${cur==="EUR"?"selected":""}>EUR (€)</option><option value="PLN" ${cur==="PLN"?"selected":""}>PLN (zł)</option><option value="RUB" ${cur==="RUB"?"selected":""}>RUB (₽)</option></select></label>
  ${subs.map((sub,i)=>`<div class="subgoal"><div class="sub-edit-row"><b>${esc(sub.title)}</b><button type="button" class="secondary goal-edit-icon" data-edit-sub="${g.id}:${i}" aria-label="Изменить подцель" title="Изменить подцель">✎</button><button type="button" class="delete" data-delete-subgoal="${g.id}:${i}">Удалить</button></div><label class="subgoal-done"><input type="checkbox" data-sub-done="${g.id}:${i}" ${sub.completed===true||sub.doneDate?"checked":""}> Выполнено</label><p>Срок: ${sub.days||0} дней<br>Исполнение: ${esc(sub.doneDate||"Не указано")}<br>Стоимость: ${money(sub.cost,cur)}<br>Плановая дата: ${esc(sub.due||"Не указана")}</p></div>`).join("")}
  <button type="button" class="secondary add-subgoal-toggle" data-add-subgoal="${g.id}">Добавить подцель</button><button type="button" class="delete" data-delete-goal="${g.id}">Удалить цель</button><form class="subgoal-form" data-goal="${g.id}" hidden><label>Название подцели<input name="title" required></label><div class="two"><label>Срок (дней)<input name="days" type="number" min="0" step="1" value="0"></label><label>Стоимость (${currencySymbol(cur)})<input name="cost" type="number" min="0" step="0.01" value="0"></label></div><label>Дата исполнения<input name="due" type="date"></label><button class="primary">Сохранить подцель</button></form></details></article>`;
 }).join("")||"<p class='muted'>Пока нет целей. Они появятся здесь после оценки идеи как «Адекватная».</p>";
}

document.querySelector("#standalone-goal-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,v=formObject(f);const title=v.title.trim();if(!title)return;await add("goals",{title,currency:v.currency||"EUR",createdAt:new Date().toISOString(),subgoals:[],ideaId:null,independent:true});f.reset();renderGoals();});
document.querySelector("#goals-list").addEventListener("submit",async e=>{const f=e.target.closest(".subgoal-form");if(!f)return;e.preventDefault();const g=(await all("goals")).find(x=>x.id===Number(f.dataset.goal));if(!g)return;const v=formObject(f);g.subgoals=[...(g.subgoals||[]),{title:v.title,days:Number(v.days)||0,cost:Number(v.cost)||0,due:v.due||"",doneDate:"",completed:false}];await put("goals",g);renderGoals();});
document.querySelector("#goals-list").addEventListener("change",async e=>{const currency=e.target.closest("[data-goal-currency]");if(currency){const g=(await all("goals")).find(x=>x.id===Number(currency.dataset.goalCurrency));if(g){g.currency=currency.value;await put("goals",g);renderGoals();}return;}const done=e.target.closest("[data-sub-done]");if(done){const [gid,idx]=done.dataset.subDone.split(":").map(Number),g=(await all("goals")).find(x=>x.id===gid);if(!g||!g.subgoals?.[idx])return;g.subgoals[idx].completed=done.checked;if(done.checked&&!g.subgoals[idx].doneDate)g.subgoals[idx].doneDate=localDate();if(!done.checked)g.subgoals[idx].doneDate="";await put("goals",g);renderGoals();}});
document.querySelector("#goals-list").addEventListener("click",async e=>{const delSub=e.target.closest("[data-delete-subgoal]");if(delSub){const [gid,idx]=delSub.dataset.deleteSubgoal.split(":").map(Number),g=(await all("goals")).find(x=>x.id===gid);if(g&&confirm(trUI("Удалить подцель?"))){g.subgoals.splice(idx,1);await put("goals",g);renderGoals();}return;}const delGoal=e.target.closest("[data-delete-goal]");if(delGoal){const g=(await all("goals")).find(x=>x.id===Number(delGoal.dataset.deleteGoal));if(g&&confirm(trUI("Удалить цель вместе со всеми подцелями?"))){if(g.ideaId){const idea=(await all("criticality")).find(x=>x.id===g.ideaId);if(idea){idea.goalDeleted=true;await put("criticality",idea);}}await remove("goals",g.id);renderGoals();}return;}const addToggle=e.target.closest("[data-add-subgoal]");if(addToggle){const form=document.querySelector(`.subgoal-form[data-goal="${addToggle.dataset.addSubgoal}"]`);if(form)form.hidden=!form.hidden;return;}const goalBtn=e.target.closest("[data-edit-goal]");if(goalBtn){const g=(await all("goals")).find(x=>x.id===Number(goalBtn.dataset.editGoal));if(!g)return;const title=prompt(trUI("Название цели"),g.title);if(title===null)return;const days=prompt(trUI("Итоговый срок в днях (пусто = сумма подцелей)"),g.daysOverride??"");if(days===null)return;const cost=prompt(trUI(`Итоговая стоимость (${currencySymbol(g.currency||"EUR")}) (пусто = сумма подцелей)`),g.costOverride??"");if(cost===null)return;g.title=title;g.daysOverride=days.trim()===""?null:Number(days);g.costOverride=cost.trim()===""?null:Number(cost);await put("goals",g);renderGoals();return;}const b=e.target.closest("[data-edit-sub]");if(!b)return;const [gid,idx]=b.dataset.editSub.split(":").map(Number),g=(await all("goals")).find(x=>x.id===gid);if(!g)return;const sub=g.subgoals[idx];const title=prompt(trUI("Название подцели"),sub.title);if(title===null)return;const days=prompt(trUI("Срок в днях"),sub.days);if(days===null)return;const due=prompt(trUI("Плановая дата исполнения (ГГГГ-ММ-ДД)"),sub.due||"");if(due===null)return;const done=prompt(trUI("Фактическая дата исполнения (ГГГГ-ММ-ДД), оставь пустым если не выполнено"),sub.doneDate||"");if(done===null)return;const cost=prompt(trUI(`Стоимость (${currencySymbol(g.currency||"EUR")})`),sub.cost);if(cost===null)return;g.subgoals[idx]={...sub,title,days:Number(days)||0,due,doneDate:done,cost:Number(cost)||0,completed:!!done||sub.completed};await put("goals",g);renderGoals();});

document.querySelector("#idea-list").addEventListener("click",async e=>{const b=e.target.closest("[data-delete-idea]");if(!b)return;const id=Number(b.dataset.deleteIdea);if(!confirm(trUI("Удалить идею и связанную с ней цель?")))return;const goals=await all("goals");for(const g of goals)if(g.ideaId===id)await remove("goals",g.id);await remove("criticality",id);await renderIdeas();await renderGoals();});
document.querySelector("#idea-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,v=formObject(f),day=v.date.slice(0,10),moods=await all("mood"),same=moods.filter(m=>(m.date||"").slice(0,10)===day&&m.phase).sort((a,b)=>(b.date||"").localeCompare(a.date||""));v.phase=same[0]?.phase||"";await add("criticality",v);f.reset();f.elements.date.value=localDateTime();renderIdeas();await syncGoals();renderGoals();});
// Excel-compatible XML workbook with one worksheet per app section; opens in Excel without external libraries or internet.
function xml(v){return String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&apos;");}
document.querySelector("#export-all").onclick=async()=>{let sheets="";for(const key of ["meds","mood","sleep","diary","traits","medLogs","traitHistory","criticality","goals"]){let records=await all(key);if(key==="sleep")records=sleepExportRows(records);if(key==="goals")records=records.flatMap(x=>(x.subgoals||[]).map(s=>({...x,...s})));if(key==="medLogs"){const meds=await all("meds");window.__medExportCache=meds;const groups={};for(const l of records){const k=[l.medId,l.date,l.period].join("|");if(!groups[k])groups[k]={...l,count:0};groups[k].count++;}records=Object.values(groups);}const rows=[exports[key].headers.map(v=>translateString(v,LANG[localStorage.getItem("my-state-language")||"ru"]||{})),...records.map(exports[key].map)];sheets+=`<Worksheet ss:Name="${xml(translateString(({meds:"Лекарства",mood:"Настроение",sleep:"Сон",diary:"Дневник",traits:"Фазы",medLogs:"Приём",traitHistory:"История",criticality:"Критичность",goals:"Цели"})[key],LANG[localStorage.getItem("my-state-language")||"ru"]||{}))}"><Table>${rows.map(r=>`<Row>${r.map(v=>`<Cell><Data ss:Type="String">${xml(v)}</Data></Cell>`).join("")}</Row>`).join("")}</Table></Worksheet>`;}const indexSheet=`<Worksheet ss:Name="Содержание"><Table><Row><Cell><Data ss:Type="String">${xml(translateString("Разделы книги",LANG[localStorage.getItem("my-state-language")||"ru"]||{}))}</Data></Cell></Row>${["Лекарства","Настроение","Сон","Дневник","Фазы","Приём","История","Критичность","Цели"].map(n=>`<Row><Cell><Data ss:Type="String">${xml(translateString(n,LANG[localStorage.getItem("my-state-language")||"ru"]||{}))}</Data></Cell></Row>`).join("")}</Table></Worksheet>`;const book=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">${indexSheet}${sheets}</Workbook>`;download("moe-sostoyanie-excel.xls",book,"application/vnd.ms-excel;charset=utf-8");};
document.querySelector("#backup").onclick=async()=>{
 try{const data={format:"my-state-backup",version:5,exportedAt:new Date().toISOString(),emergencyContacts:readContacts()};for(const s of STORES)data[s]=await all(s);
 download("my-state-backup.json",JSON.stringify(data,null,2),"application/json;charset=utf-8");
 }catch(err){console.error(err);document.querySelector("#export-status").textContent="Не удалось создать резервную копию: "+err.message;}
};
document.querySelector("#restore-backup").addEventListener("change",async e=>{
 const file=e.target.files?.[0];if(!file)return;
 try{
  const raw=(await file.text()).replace(/^\uFEFF/,"");let parsed=JSON.parse(raw);
  // Accept backups from earlier app releases, including exports with a data wrapper.
  const data=parsed?.data&&typeof parsed.data==="object"?{...parsed,...parsed.data}:parsed;
  const hasStore=STORES.some(s=>Array.isArray(data?.[s]));
  if(!data||typeof data!=="object"||(!hasStore&&data.format!=="my-state-backup")||(data.format&&data.format!=="my-state-backup"))throw new Error("Неверный формат резервной копии. Выбери JSON-файл, созданный кнопкой «Скачать резервную копию».");
  for(const s of STORES){if(data[s]!==undefined&&!Array.isArray(data[s]))throw new Error("Повреждён раздел "+s);if((data[s]||[]).some(item=>!item||typeof item!=="object"||Array.isArray(item)||!("id" in item)))throw new Error("Повреждённая запись в разделе "+s);}

  if(!confirm(trUI("Восстановление заменит все текущие записи данными из файла. Продолжить?")))return;
  await new Promise((resolve,reject)=>{
   const tx=db.transaction(STORES,"readwrite");
   for(const s of STORES){const os=tx.objectStore(s);os.clear();for(const item of (data[s]||[]))os.put(item);}
   tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Транзакция прервана"));
  });
  if(Array.isArray(data.emergencyContacts))saveContacts(data.emergencyContacts.filter(c=>c&&typeof c==="object").map(c=>({name:String(c.name||""),phone:String(c.phone||"")})));
  renderContacts();await refreshAll();alert(trUI("Данные восстановлены."));
 }catch(err){console.error(err);alert("Не удалось восстановить копию: "+err.message);}
 finally{e.target.value="";}
});

// Emergency contacts are stored only in this browser. tel: links hand off to the phone app.
const CONTACTS_KEY="my-state-emergency-contacts";
function readContacts(){try{const a=JSON.parse(localStorage.getItem(CONTACTS_KEY)||"[]");return Array.isArray(a)?a:[];}catch{return [];}}
function saveContacts(items){localStorage.setItem(CONTACTS_KEY,JSON.stringify(items));}
function renderContacts(){const host=document.querySelector("#emergency-contacts");if(!host)return;const items=readContacts();host.innerHTML=items.map((c,i)=>`<div class="contact-row" data-contact-row="${i}"><input class="contact-name" aria-label="Имя контакта" value="${esc(c.name||"")}" readonly><a class="contact-phone" href="tel:${esc((c.phone||"").replace(/[^+0-9*#]/g,""))}">${esc(c.phone||"Номер телефона")}</a><button type="button" class="secondary contact-edit" data-contact-edit="${i}" aria-label="Редактировать контакт">✎</button><button type="button" class="delete contact-delete" data-contact-delete="${i}" aria-label="Удалить контакт">×</button></div>`).join("");}
document.querySelector("#add-contact").addEventListener("click",()=>{const items=readContacts();items.push({name:"",phone:""});saveContacts(items);renderContacts();const row=document.querySelector(`[data-contact-row="${items.length-1}"]`);row.innerHTML=`<input class="contact-name" aria-label="Имя контакта" placeholder="Имя"><input class="contact-phone-input" type="tel" aria-label="Номер телефона" placeholder="Номер телефона"><button type="button" class="secondary" data-contact-save="${items.length-1}">✓</button>`;row.querySelector(".contact-name").focus();});
document.querySelector("#emergency-contacts").addEventListener("click",e=>{const edit=e.target.closest("[data-contact-edit]");if(edit){const i=Number(edit.dataset.contactEdit),c=readContacts()[i],row=edit.closest(".contact-row");row.innerHTML=`<input class="contact-name" aria-label="Имя контакта" value="${esc(c.name||"")}" placeholder="Имя"><input class="contact-phone-input" type="tel" aria-label="Номер телефона" value="${esc(c.phone||"")}" placeholder="Номер телефона"><button type="button" class="secondary" data-contact-save="${i}">✓</button>`;row.querySelector(".contact-name").focus();return;}const save=e.target.closest("[data-contact-save]");if(save){const i=Number(save.dataset.contactSave),row=save.closest(".contact-row"),items=readContacts();items[i]={name:row.querySelector(".contact-name").value.trim(),phone:row.querySelector(".contact-phone-input").value.trim()};saveContacts(items);renderContacts();return;}const del=e.target.closest("[data-contact-delete]");if(del){const i=Number(del.dataset.contactDelete),items=readContacts();if(confirm(trUI("Удалить контакт?"))){items.splice(i,1);saveContacts(items);renderContacts();}}});
renderContacts();

// Home shortcuts control which section tabs are pinned. Export is always available.
const PIN_KEYS=["mood","sleep","diary","meds","personality","criticality","goals"];
function applyPinnedTabs(){
 const saved=JSON.parse(localStorage.getItem("my-state-pinned")||"null")||Object.fromEntries(PIN_KEYS.map(k=>[k,true]));
 document.querySelectorAll("[data-pin]").forEach(c=>c.checked=saved[c.dataset.pin]!==false);
 document.querySelectorAll(".tab[data-view]").forEach(t=>{const k=t.dataset.view;t.hidden=PIN_KEYS.includes(k)&&saved[k]===false;});
 localStorage.setItem("my-state-pinned",JSON.stringify(saved));
}
document.querySelectorAll("[data-pin]").forEach(c=>c.addEventListener("change",()=>{
 const saved=JSON.parse(localStorage.getItem("my-state-pinned")||"{}");saved[c.dataset.pin]=c.checked;localStorage.setItem("my-state-pinned",JSON.stringify(saved));applyPinnedTabs();
}));
applyPinnedTabs();

// Currency affects display only; stored numeric amounts are never recalculated.
const CURRENCIES={EUR:{symbol:"€",label:"евро"},PLN:{symbol:"zł",label:"злотых"},RUB:{symbol:"₽",label:"рублей"}};
function currencySymbol(currency="EUR"){return (CURRENCIES[currency]||CURRENCIES.EUR).symbol;}
function money(value,currency="EUR"){return `${Number(value||0).toFixed(2)} ${currencySymbol(currency)}`;}
